     }
     if (character === '"' || character === "'") { quote = character; continue; }
     if (character === "(") { depth += 1; continue; }
     if (character === ")") { depth = Math.max(0, depth - 1); continue; }
     if (character === "," && depth === 0) {
       result.push(argumentsText.slice(start, index).trim());
