from PIL import Image
import math

def load(p):
    return Image.open(p).convert('RGB')

def dist(a, b):
    return math.sqrt(sum((x-y)**2 for x, y in zip(a, b)))

COLORS = {
    'stage': (224, 242, 254),
    'neg':   (196, 181, 253),
    'auto':  (254, 240, 138),
    'zero':  (134, 239, 172),
    'pos':   (251, 113, 133),
}

def bbox(im, target, tol=48):
    px = im.load()
    W, H = im.size
    xs, ys = [], []
    for y in range(H):
        for x in range(W):
            if dist(px[x, y], target) < tol:
                xs.append(x); ys.append(y)
    if not xs: return None
    return (min(xs), min(ys), max(xs), max(ys), len(xs))

for p in ['/tmp/dbg_browser.png', '/tmp/dbg_penpot.png']:
    im = load(p)
    print('===', p)
    for name, col in COLORS.items():
        print(f'  {name:6s}', bbox(im, col))
EOF

