import math

def dist(a, b):
    return math.sqrt(sum((x-y)**2 for x, y in zip(a, b)))

COLORS = {
    'neg':   (196, 181, 253),
    'auto':  (254, 240, 138),
    'zero':  (134, 239, 172),
    'pos':   (251, 113, 133),
}

im = Image.open('/tmp/fresh_mobile.png').convert('RGB')
print('size', im.size)
px = im.load()
W, H = im.size
for name, col in COLORS.items():
    xs, ys = [], []
    for y in range(H):
        for x in range(W):
            if dist(px[x, y], col) < 30:
                xs.append(x); ys.append(y)
    if xs:
        print(f'  {name:5s} x0={min(xs):4d} y0={min(ys):4d} x1={max(xs):4d} y1={max(ys):4d} px={len(xs)}')
EOF

