import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { importScenes } from "./penpot";

type FakeShape = Record<string, unknown> & { type: string; children?: FakeShape[] };

function fakeShape(type: string): FakeShape {
  return {
    type,
    name: "",
    x: 0,
    y: 0,
    children: [],
    pluginData: {},
    resize: vi.fn(function (this: FakeShape, width: number, height: number) { this.width = width; this.height = height; }),
    setPluginData: vi.fn(function (this: FakeShape, key: string, value: string) { (this.pluginData as Record<string, string>)[key] = value; }),
    getPluginData: vi.fn(function (this: FakeShape, key: string) { return String((this.pluginData as Record<string, string>)[key] || ""); }),
    appendChild: vi.fn(function (this: FakeShape, child: FakeShape) { this.children?.push(child); }),
    remove: vi.fn()
  };
}

describe("geometry debug", () => {
  let boards: FakeShape[];
  beforeEach(() => {
    boards = [];
    vi.stubGlobal("penpot", {
      viewport: { center: { x: 0, y: 0 } },
      history: { undoBlockBegin: vi.fn(() => Symbol("undo")), undoBlockFinish: vi.fn() },
      createBoard: vi.fn(() => { const board = fakeShape("board"); boards.push(board); return board; }),
      createRectangle: vi.fn(() => fakeShape("rectangle")),
      createText: vi.fn((characters: string) => Object.assign(fakeShape("text"), { characters, growType: "fixed", width: 0 })),
      group: vi.fn((shapes: FakeShape[]) => Object.assign(fakeShape("group"), { children: shapes })),
      createShapeFromSvg: vi.fn(() => null),
      createShapeFromSvgWithImages: vi.fn(),
      uploadMediaData: vi.fn().mockResolvedValue({}),
      uploadMediaUrl: vi.fn().mockResolvedValue({})
    });
  });

  it("dumps stacking layer geometry", async () => {
    const evidence = JSON.parse(readFileSync(resolve(process.cwd(), "src/capture/fixtures/baselines/scene-evidence.json"), "utf8"));
    const fixture = evidence.fixtures.find((f: { file: string }) => f.file === "stacking-contents-whitespace.html");
    const scene = fixture.viewports[0].scene;
    const dump: unknown[] = [];
    const walk = (shape: FakeShape, depth: number): void => {
      const pluginData = shape.pluginData as Record<string, string>;
      if (pluginData.source?.startsWith("#stack")) {
        dump.push({ depth, type: shape.type, source: pluginData.source, x: shape.x, y: shape.y, width: shape.width, height: shape.height, strokes: shape.strokes });
      }
      for (const child of shape.children || []) walk(child, depth + 1);
    };
    const result = await importScenes([scene], { isCancelled: () => false, onProgress: vi.fn() });
    for (const board of result as unknown as FakeShape[]) walk(board, 0);
    process.stdout.write(`GEOMETRY-DUMP ${JSON.stringify(dump)}\n`);
    const expected: Record<string, { x: number; y: number }> = {};
    for (const node of scene.nodes) {
      if (typeof node.source === "string" && node.source.startsWith("#stack") && !node.source.includes("::text")) {
        expected[node.source] = node.rect;
      }
    }
    process.stdout.write(`EXPECTED ${JSON.stringify(expected)}\n`);
    expect(true).toBe(true);
  });
});

