+import { describe, expect, it } from "vitest";
+import { captureViewportSize } from "./sandbox";
+import type { ViewportSpec } from "../shared/contracts";
+
+const mobile: ViewportSpec = { id: "mobile", name: "Mobile", width: 390, height: 844 };
+
+describe("capture viewport sizing", () => {
+  it("matches Chrome's default mobile layout viewport without changing source HTML", () => {
+    const html = "<main>content</main>";
+    expect(captureViewportSize(html, mobile)).toEqual({ width: 980, height: 2121 });
+    expect(html).toBe("<main>content</main>");
+  });
+
+  it("keeps device-width pages at the requested mobile dimensions", () => {
+    expect(captureViewportSize("<meta name=viewport content=\"width=device-width, initial-scale=1\">", mobile)).toEqual({ width: 390, height: 844 });
+  });
+
+  it("does not apply mobile layout emulation to desktop boards", () => {
+    const desktop: ViewportSpec = { id: "desktop", name: "Desktop", width: 1440, height: 900 };
+    expect(captureViewportSize("<main>content</main>", desktop)).toEqual({ width: 1440, height: 900 });
+  });
+});

