     const visible = { ...root, id: "visible", parentId: "outer", children: ["inner"], name: "visible wrapper", source: "body > section > div", rect: { x: 0, y: 0, width: 200, height: 100 }, paint: { backgroundColor: "rgb(1, 2, 3)" } };
