const DEFAULT_MOBILE_LAYOUT_WIDTH = 980;

function htmlAttribute(tag, name) {
  const match = tag.match(new RegExp(`\\b${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, "i"));
  return match?.[1] || match?.[2] || match?.[3] || "";
}

function captureLayoutSize(source, viewport) {
  if (viewport.id !== "mobile") return { width: viewport.width, height: viewport.height };
  const meta = [...source.toString("utf8").matchAll(/<meta\b[^>]*>/gi)]
    .map((match) => match[0])
    .find((tag) => htmlAttribute(tag, "name").trim().toLowerCase() === "viewport");
  const content = htmlAttribute(meta || "", "content");
  const widthToken = content.match(/(?:^|,)\s*width\s*=\s*([^,\s]+)/i)?.[1]?.toLowerCase();
  const width = widthToken === "device-width" ? viewport.width : Number(widthToken);
  const layoutWidth = Number.isFinite(width) && width > 0 ? width : DEFAULT_MOBILE_LAYOUT_WIDTH;
  return layoutWidth === viewport.width
    ? { width: layoutWidth, height: viewport.height }

