+export function captureViewportSize(html: string, viewport: ViewportSpec): { width: number; height: number } {
+  if (viewport.id !== "mobile") return { width: viewport.width, height: viewport.height };
+  const width = mobileLayoutWidth(html, viewport.width);
+  if (width === viewport.width) return { width, height: viewport.height };
+  return { width, height: Math.ceil(viewport.height * width / viewport.width) };
