 function resolvedGradientOffsets(stops: GradientStop[]): number[] {
   const offsets = stops.map((stop) => stop.offset);
   if (offsets[0] === undefined) offsets[0] = 0;
   if (offsets[offsets.length - 1] === undefined) offsets[offsets.length - 1] = 1;
